//! Run Claude Code inside a Ship-managed container with the user's real
//! OAuth credentials and a workspace mount.
//!
//! Usage:
//!   cargo run -p ship-isolation --features youki-backend \
//!       --example run_claude -- <workspace> "<prompt>"
//!
//! Env overrides:
//!   SHIP_YOUKI_BIN          (default: /tmp/youki)
//!   SHIP_YOUKI_SPEC         (default: /tmp/claude-bundle/config.json
//!                            — generated by `youki spec --rootless`)
//!   SHIP_AGENT_ROOTFS       (default: /tmp/ship-rootfs/rootfs
//!                            — generated by scripts/build_agent_rootfs.sh)
//!   SHIP_CLAUDE_CREDENTIALS (default: $HOME/.claude/.credentials.json)
//!
//! On first run with no rootfs yet:
//!   scripts/build_agent_rootfs.sh
//!
//! The example builds a SandboxPolicy with workspace + credentials bind
//! mounts and `NetworkPolicy::Open` (share host net for the spike), spins
//! up a youki container, and runs `/opt/bun/bin/claude --print "<prompt>"`
//! inside. Stdio is inherited so the model's response appears directly.

#![cfg(all(feature = "youki-backend", target_os = "linux"))]

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use ship_isolation::backends::{Youki, YoukiConfig};
use ship_isolation::{
    EphemeralFile, FsMount, Isolator, LaunchCommand, MountMode, NetworkPolicy, SandboxPolicy,
};

fn env_path(name: &str, default: &str) -> PathBuf {
    PathBuf::from(std::env::var(name).unwrap_or_else(|_| default.into()))
}

fn must_exist(path: &Path, kind: &str) -> Result<(), String> {
    let ok = match kind {
        "file" => path.is_file(),
        "dir" => path.is_dir(),
        _ => path.exists(),
    };
    if ok {
        Ok(())
    } else {
        Err(format!("{kind} not found: {}", path.display()))
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = std::env::args().skip(1);
    let workspace = PathBuf::from(args.next().ok_or("usage: run_claude <workspace> <prompt>")?);
    let prompt = args.next().unwrap_or_else(|| "Say hello in one word.".into());

    let youki_bin = env_path("SHIP_YOUKI_BIN", "/tmp/youki");
    let spec_template = env_path("SHIP_YOUKI_SPEC", "/tmp/claude-bundle/config.json");
    let rootfs = env_path("SHIP_AGENT_ROOTFS", "/tmp/ship-rootfs/rootfs");
    let creds = env_path(
        "SHIP_CLAUDE_CREDENTIALS",
        &format!(
            "{}/.claude/.credentials.json",
            std::env::var("HOME").unwrap_or_default()
        ),
    );

    must_exist(&youki_bin, "file")?;
    must_exist(&spec_template, "file")?;
    must_exist(&rootfs, "dir")?;
    must_exist(&workspace, "dir")?;
    must_exist(&creds, "file")?;

    let state_root = std::env::temp_dir().join(format!("ship-run-claude-{}", std::process::id()));
    tokio::fs::create_dir_all(&state_root).await?;

    let backend = Youki::new(YoukiConfig {
        youki_bin,
        spec_template,
        rootfs,
        state_root: state_root.clone(),
    });
    backend.available().await?;

    // Option B: copy host credentials into a Ship-owned ephemeral file,
    // bind-mount that into the container. The host's real
    // ~/.claude/.credentials.json is never bind-mounted directly.
    let ephem_creds = EphemeralFile::copy_from(&creds).await?;

    let mut policy = SandboxPolicy {
        label: "run-claude".into(),
        ..SandboxPolicy::default()
    };
    policy.network = NetworkPolicy::Open;
    policy.mounts = vec![
        FsMount {
            host_path: workspace.clone(),
            sandbox_path: PathBuf::from("/work"),
            mode: MountMode::ReadWrite,
        },
        ephem_creds.as_mount(PathBuf::from("/root/.claude/.credentials.json")),
        FsMount {
            host_path: PathBuf::from("/etc/resolv.conf"),
            sandbox_path: PathBuf::from("/etc/resolv.conf"),
            mode: MountMode::ReadOnly,
        },
    ];

    let handle = backend.prepare(&policy).await?;

    let mut env = HashMap::new();
    env.insert("HOME".into(), "/root".into());
    env.insert(
        "PATH".into(),
        "/opt/bun/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin".into(),
    );
    env.insert("TERM".into(), "dumb".into());

    let cmd = LaunchCommand {
        bin: PathBuf::from("/opt/bun/bin/claude"),
        args: vec!["--print".into(), prompt],
        env,
        cwd: PathBuf::from("/work"),
    };

    eprintln!("ship-isolation: spawning claude in container...");
    let code = backend.run_to_completion(&handle, cmd).await?;
    eprintln!("ship-isolation: claude exited with {:?}", code);

    backend.shutdown(handle).await?;
    drop(ephem_creds);
    let _ = tokio::fs::remove_dir_all(&state_root).await;

    std::process::exit(code.unwrap_or(0));
}
